    input a, b,
    output and_out, or_out, nand_out, nor_out, notb_out, xor_out, xnor_out
);
    // Write your code here
    // Use only assign statements with operators:
    // &, |, ~&, ~|, ~, ^, ~^

endmodule

testbench:
`timescale 1ns/1ps
module tb();
    reg a, b;
    wire and_out, or_out, nand_out, nor_out, notb_out, xor_out, xnor_out;
    integer passed = 0;

    data_flow dut (.a(a), .b(b), .and_out(and_out), .or_out(or_out), .nand_out(nand_out), .nor_out(nor_out), .notb_out(notb_out), .xor_out(xor_out), .xnor_out(xnor_out));

    initial begin
        $display("Testing Dataflow Logic Gates...");

        a=0; b=0; #10;
        if(!(and_out===0 && or_out===0 && nand_out===1 && nor_out===1 && notb_out===1 && xor_out===0 && xnor_out===1)) $display("FAIL: 00 input"); 
        else passed++;

        a=1; b=1; #10;
        if(!(and_out===1 && or_out===1 && nand_out===0 && nor_out===0 && notb_out===0 && xor_out===0 && xnor_out===1)) $display("FAIL: 11 input"); 
        else passed++;

        if(passed==2) $display("PASS: All gate outputs correct"); 
        else $display("FAIL: Some outputs incorrect");
        $finish;
    end
endmodule

solution:
module data_flow(
    input a, b,
    output and_out, or_out, nand_out, nor_out, notb_out, xor_out, xnor_out
);
    assign and_out = a & b;
    assign or_out = a | b;
    assign nand_out = ~(a & b);
    assign nor_out = ~(a | b);
    assign notb_out = ~b;
    assign xor_out = a ^ b;
    assign xnor_out = a ~^ b;
endmodule

