module and_or_xor_select (
    input wire [7:0] a,
    input wire [7:0] b,
    input wire [1:0] sel,
    output reg [7:0] y
);
    always @(*) begin
        case (sel)
            2'd0: y = a & b;
            2'd1: y = a | b;
            2'd2: y = a ^ b;
            default: y = ~(a ^ b);
        endcase
    end
endmodule

