module bcd_add2digit (
    input wire [7:0] a,
    input wire [7:0] b,
    output wire [7:0] y,
    output wire carry
);
    wire [4:0] u = a[3:0] + b[3:0];
    wire u_carry = (u > 5'd9);
    wire [3:0] u_res = u_carry ? (u - 5'd10) : u[3:0];
    wire [4:0] t = a[7:4] + b[7:4] + u_carry;
    wire t_carry = (t > 5'd9);
    wire [3:0] t_res = t_carry ? (t - 5'd10) : t[3:0];
    assign y = {t_res, u_res};
    assign carry = t_carry;
endmodule

