module Booth_Multiplier(
    input signed [3:0] A,
    input signed [3:0] B,
    output reg signed [7:0] PRODUCT
);
    reg [1:0] temp;
    integer i;
    reg e;
    reg signed [7:0] acc;
    reg signed [7:0] B_ext;
    always @(*) begin
        acc = 8'd0;
        B_ext = {{4{B[3]}}, B};
        e = 1'b0;
        for (i = 0; i < 4; i = i + 1) begin
            temp = {A[i], e};
            case (temp)
                2'b01: acc = acc + (B_ext << i);
                2'b10: acc = acc - (B_ext << i);
                default: ;
            endcase
            e = A[i];
        end
        PRODUCT = acc;
    end
endmodule

