solution:
module carry_save_adder(
    input [3:0] a, b, c,
    output [4:0] sum,
    output cout
);
    wire [3:0] sum_temp, carry_temp;
    assign sum_temp[0] = a[0] ^ b[0] ^ c[0];
    assign sum_temp[1] = a[1] ^ b[1] ^ c[1];
    assign sum_temp[2] = a[2] ^ b[2] ^ c[2];
    assign sum_temp[3] = a[3] ^ b[3] ^ c[3];
    assign carry_temp[0] = (a[0] & b[0]) | (a[0] & c[0]) | (b[0] & c[0]);
    assign carry_temp[1] = (a[1] & b[1]) | (a[1] & c[1]) | (b[1] & c[1]);
    assign carry_temp[2] = (a[2] & b[2]) | (a[2] & c[2]) | (b[2] & c[2]);
    assign carry_temp[3] = (a[3] & b[3]) | (a[3] & c[3]) | (b[3] & c[3]);
    // Final add: sum_temp + (carry_temp << 1).  Max value 45 -> needs 6 bits,
    // so zero-extend both operands to 6 bits to avoid truncation.
    assign {cout, sum} = {2'b0, sum_temp} + {1'b0, carry_temp, 1'b0};
endmodule

