module shift_add_mul4 (
    input wire clk,
    input wire rst,
    input wire start,
    input wire [3:0] a,
    input wire [3:0] b,
    output reg [7:0] product,
    output reg done
);
    // The multiplicand must be 8 bits wide: it is shifted left three times,
    // so a 4-bit register would silently drop the top bits (15<<3 = 120).
    reg [7:0] acc;
    reg [7:0] mcand;
    reg [3:0] mplier;
    reg [2:0] cnt;
    reg running;
    always @(posedge clk)
        if (rst) begin
            acc <= 8'd0; mcand <= 8'd0; mplier <= 4'd0; cnt <= 3'd0;
            product <= 8'd0; done <= 1'b0; running <= 1'b0;
        end else if (!running) begin
            done <= 1'b0;
            if (start) begin
                acc <= 8'd0;
                mcand <= {4'd0, a};
                mplier <= b;
                cnt <= 3'd0;
                running <= 1'b1;
            end
        end else begin
            if (mplier[0]) acc <= acc + mcand;
            mcand <= mcand << 1;
            mplier <= mplier >> 1;
            cnt <= cnt + 3'd1;
            if (cnt == 3'd3) begin
                product <= mplier[0] ? (acc + mcand) : acc;
                running <= 1'b0;
                done <= 1'b1;
            end
        end
endmodule

