module decoder_2to4(
    input a,
    input b,
    output reg [3:0] y
);
    always @(*) begin
        case ({a, b})
            2'b00: y = 4'b0001;
            2'b01: y = 4'b0010;
            2'b10: y = 4'b0100;
            2'b11: y = 4'b1000;
            default: y = 4'b0000;
        endcase
    end
endmodule

module comparator_2bit_decoder(
    input a1, a0, b1, b0,
    output less,
    output greater,
    output equal
);
    wire [3:0] yA, yB;
    decoder_2to4 decA(.a(a1), .b(a0), .y(yA));
    decoder_2to4 decB(.a(b1), .b(b0), .y(yB));
    // yA / yB are one-hot: bit i set means the value is i.
    // A > B  iff  A's set bit index > B's set bit index.
    assign greater = (yA[3] & (yB[2] | yB[1] | yB[0])) |
                     (yA[2] & (yB[1] | yB[0])) |
                     (yA[1] &  yB[0]);
    assign less    = (yB[3] & (yA[2] | yA[1] | yA[0])) |
                     (yB[2] & (yA[1] | yA[0])) |
                     (yB[1] &  yA[0]);
    assign equal   = (yA == yB);
endmodule

