module comparator_signed_unsigned(
    input [3:0] a,
    input [3:0] b,
    input c,
    output g,
    output l,
    output e
);
    wire signed_eq, signed_gt, signed_lt;
    wire uns_eq, uns_gt, uns_lt;
    assign uns_eq = (a == b);
    assign uns_gt = (a > b);
    assign uns_lt = (a < b);
    assign signed_eq = (a == b);
    assign signed_gt = (a[3] == b[3]) ? (a > b) : (~a[3]);
    assign signed_lt = (a[3] == b[3]) ? (a < b) : (a[3]);
    assign g = c ? signed_gt : uns_gt;
    assign l = c ? signed_lt : uns_lt;
    assign e = c ? signed_eq : uns_eq;
endmodule

