module keypad (
    input wire [3:0] row,
    input wire [3:0] col,
    output reg [3:0] key,
    output reg valid
);
    integer i, j;
    always @(*) begin
        key = 4'd0; valid = 1'b0;
        for (i = 0; i < 4; i = i + 1)
            for (j = 0; j < 4; j = j + 1)
                if (row[i] && col[j]) begin
                    key = (i << 2) | j;
                    valid = 1'b1;
                end
    end
endmodule

