    always #5 clk = ~clk;
    initial begin
        $display("== CRC-8 Dallas/Maxim ==");
        @(posedge clk); #1 rst=0;
        @(negedge clk); start=1; b=0;
        @(posedge clk); #1;
        @(negedge clk); start=0;
        for (i=0; i<8; i=i+1) begin
            b = data[i];
            @(posedge clk); #1;
        end
        // For 0x12 with Dallas/Maxim CRC-8 (poly 0x31, init 0x00) result is 0x84
        if (crc===8'h84) pass=pass+1; else begin fail=fail+1; $display("FAIL: crc=%h", crc); end
