solution:
module crc8_maxim (
    input wire clk,
    input wire rst,
    input wire start,
    input wire bit_in,
    output reg [7:0] crc
);
    reg [7:0] state;
    always @(posedge clk)
        if (rst) begin
            state <= 8'h00;
        end else if (start) begin
            state <= 8'h00;
        end else begin
            // feedback = bit_in XOR state[7]
            state[7] <= state[6];
            state[6] <= state[5];
            state[5] <= state[4] ^ bit_in ^ state[7];
            state[4] <= state[3] ^ bit_in ^ state[7];
            state[3] <= state[2];
            state[2] <= state[1];
            state[1] <= state[0];
            state[0] <= bit_in ^ state[7];
        end
    always @(*) crc = state;
endmodule

