template:
module hamming74_dec (
    input wire [6:0] codeword,
    output reg [3:0] data,
    output reg corrected
);
    // codeword[0]=bit1 ... codeword[6]=bit7
    // data = {d4,d3,d2,d1}
endmodule

testbench:
`timescale 1ns/1ps
module tb();
    reg [6:0] cw;
    wire [3:0] d;
    wire corr;
    integer pass=0, fail=0;
    hamming74_dec dut(.codeword(cw), .data(d), .corrected(corr));
    initial begin
        $display("== Hamming(7,4) Decoder ==");
        // Literals are written MSB-first, so 7'b<c7><c6><c5><c4><c3><c2><c1>
        // i.e. the leftmost bit is codeword[6] = position 7.
        // data d1..d4 = 1011 -> p1=0 p2=1 p4=0 -> positions 1..7 = 0,1,1,0,0,1,1
        cw = 7'b1100110; #1;
        if (d===4'b1101 && corr===1'b0) pass=pass+1;
        else begin fail=fail+1; $display("FAIL: clean d=%b corr=%b expected d=1101 corr=0", d, corr); end
        // flip position 6 (d3) -> must be corrected
        cw = 7'b1000110; #1;
        if (d===4'b1101 && corr===1'b1) pass=pass+1;
        else begin fail=fail+1; $display("FAIL: error@6 d=%b corr=%b expected d=1101 corr=1", d, corr); end
        // flip position 1 (p1) -> data unaffected but correction reported
        cw = 7'b1100111; #1;
        if (d===4'b1101 && corr===1'b1) pass=pass+1;
        else begin fail=fail+1; $display("FAIL: error@1 d=%b corr=%b expected d=1101 corr=1", d, corr); end
        // flip position 4 (p4)
        cw = 7'b1101110; #1;
        if (d===4'b1101 && corr===1'b1) pass=pass+1;
        else begin fail=fail+1; $display("FAIL: error@4 d=%b corr=%b expected d=1101 corr=1", d, corr); end
        // all-zero codeword, no error
        cw = 7'b0000000; #1;
        if (d===4'b0000 && corr===1'b0) pass=pass+1;
        else begin fail=fail+1; $display("FAIL: zero d=%b corr=%b expected d=0000 corr=0", d, corr); end
        // single-bit error at position 7 corrects back to all-zero
        cw = 7'b1000000; #1;
        if (d===4'b0000 && corr===1'b1) pass=pass+1;
        else begin fail=fail+1; $display("FAIL: error@7 d=%b corr=%b expected d=0000 corr=1", d, corr); end
