module hamming74_dec (
    input wire [6:0] codeword,
    output reg [3:0] data,
    output reg corrected
);
    wire s1 = codeword[0] ^ codeword[2] ^ codeword[4] ^ codeword[6];
    wire s2 = codeword[1] ^ codeword[2] ^ codeword[5] ^ codeword[6];
    wire s4 = codeword[3] ^ codeword[4] ^ codeword[5] ^ codeword[6];
    wire [2:0] syn = {s4, s2, s1};

    reg [6:0] fixed;
    always @(*) begin
        fixed = codeword;
        if (syn != 3'd0) fixed[syn - 3'd1] = ~codeword[syn - 3'd1];
        corrected = (syn != 3'd0);
        data[0] = fixed[2];   // d1
        data[1] = fixed[4];   // d2
        data[2] = fixed[5];   // d3
        data[3] = fixed[6];   // d4
    end
endmodule

