solution:
module disp2digit (
    input wire clk,
    input wire rst,
    input wire [3:0] tens,
    input wire [3:0] units,
    output reg [6:0] seg,
    output reg digit
);
    reg toggle;
    function [6:0] decode;
        input [3:0] b;
        begin
            case (b)
                4'd0: decode = 7'b1000000;
                4'd1: decode = 7'b1111001;
                4'd2: decode = 7'b0100100;
                4'd3: decode = 7'b0110000;
                4'd4: decode = 7'b0011001;
                4'd5: decode = 7'b0010010;
                4'd6: decode = 7'b0000010;
                4'd7: decode = 7'b1111000;
                4'd8: decode = 7'b0000000;
                4'd9: decode = 7'b0010000;
                default: decode = 7'b1111111;
            endcase
        end
    endfunction
    always @(posedge clk)
        if (rst) toggle <= 1'b0;
        else     toggle <= ~toggle;
    always @(*) begin
        digit = toggle;
        seg = toggle ? decode(tens) : decode(units);
    end
endmodule

