module dff_master_slave(
    input clock,
    input rst,
    input din,
    output q,
    output qbar
);
    wire qm;

    // Master is transparent while clock is low, slave while clock is high.
    // Together they behave as a positive-edge triggered flip-flop.
    d_latch master(.ctrl(~clock), .d(din), .rst(rst), .q(qm), .qbar());
    d_latch slave (.ctrl(clock),  .d(qm),  .rst(rst), .q(q),  .qbar(qbar));
endmodule

// Level-sensitive D latch with an active-high asynchronous reset
module d_latch(
    input ctrl,
    input d,
    input rst,
    output reg q,
    output qbar
);
    always @(*) begin
        if (rst)
            q = 1'b0;
        else if (ctrl)
            q = d;
    end

    assign qbar = ~q;
endmodule

