        if (rst) begin
            q <= 4'd0; cnt <= 4'd0;
        end else if (load) begin
            q <= {din, q[3:1]};
        end else begin
            // q follows the counter; the counter free-runs from 0 so the first
            // counted value is 1.
            cnt <= cnt + 4'd1;
            q   <= cnt + 4'd1;
        end
