    reg [2:0] rep_count;

    always @(posedge clock) begin
        if (rst) begin
            current_num <= 3'd1;
            rep_count   <= 3'd0;
            out         <= 3'd1;
        end
        else if (rep_count == current_num) begin
            // finished repeating current_num -> move on
            current_num <= (current_num == 3'd5) ? 3'd1 : current_num + 3'd1;
            rep_count   <= 3'd1;
            out         <= (current_num == 3'd5) ? 3'd1 : current_num + 3'd1;
        end
        else begin
            rep_count <= rep_count + 3'd1;
            out       <= current_num;
        end
    end
endmodule

