`timescale 1ns/1ps
module async_counter(
    input clk, rst,
    output [3:0] q
);
    t_flipflop_async ff0(clk,  rst, q[0]);
    t_flipflop_async ff1(q[0], rst, q[1]);
    t_flipflop_async ff2(q[1], rst, q[2]);
    t_flipflop_async ff3(q[2], rst, q[3]);
endmodule

// Negative-edge triggered T flip-flop: the next stage is clocked by the
// falling edge of the previous stage, which is what makes a ripple chain
// count in binary.
module t_flipflop_async(
    input clk, rst,
    output reg q
);
    always @(negedge clk or posedge rst) begin
        if (rst)
            q <= 1'b0;
        else
            q <= ~q;
    end
endmodule

