module bcd_cnt_ovf (
    input wire clk,
    input wire rst,
    output reg [3:0] d0,
    output reg [3:0] d1,
    output reg ovf
);
    always @(posedge clk)
        if (rst) begin
            d0<=0; d1<=0; ovf<=0;
        end else begin
            ovf <= (d0==4'd9) && (d1==4'd9);
            if (d0==4'd9) begin
                d0 <= 4'd0;
