module gray_lsb (
    input wire clk,
    input wire rst,
    output reg y
);
    // y at cycle n is LSB of the Gray code of n.  `n` and `y` update on the
    // same edge, so the Gray code has to be derived from the *next* count.
    reg [15:0] n;
    wire [15:0] nxt = n + 16'd1;
    wire [15:0] g   = nxt ^ (nxt >> 1);
    always @(posedge clk)
        if (rst) begin n <= 16'd0; y <= 1'b0; end
        else begin
            y <= g[0];
            n <= nxt;
        end
endmodule

