module pattern_010011000111 (
    input wire clk,
    input wire rst,
    output reg y
);
    // Runs of 0s and 1s with lengths 1,1,2,2,3,3,...  `val` is the value of the
    // current run; y is driven combinationally from it so the first bit of the
    // sequence (a single 0) is emitted on the cycle after reset.
    reg [3:0] cnt;
    reg [3:0] runlen;
    reg val;
    reg phase;         // 0 = run of 0s, 1 = run of 1s
    always @(posedge clk)
        if (rst) begin
            cnt <= 0; runlen <= 1; val <= 0; phase <= 0;
        end else begin
            if (cnt == runlen - 4'd1) begin
                cnt <= 0;
                if (phase == 0) begin
                    val <= 1; phase <= 1;
                end else begin
                    val <= 0; phase <= 0; runlen <= runlen + 4'd1;
                end
            end else cnt <= cnt + 4'd1;
        end
    always @(*) y = val;
endmodule

