module debruijn4 (
    input wire clk,
    input wire rst,
    output reg y
);
    // Canonical De Bruijn B(2,4) sequence: 0000 1001 1010 1111.
    // The output for the cycle is selected by the *next* index, so the first
    // bit after reset is the second bit of the sequence.
    reg [3:0] idx;
    always @(posedge clk)
        if (rst) begin
            idx <= 4'd0; y <= 1'b0;
        end else begin
            idx <= idx + 4'd1;
            case (idx + 4'd1)
                4'd4, 4'd7, 4'd8, 4'd10, 4'd12, 4'd13, 4'd14, 4'd15: y <= 1'b1;
                default: y <= 1'b0;
            endcase
        end
endmodule

