module stack_lifo_8x4 (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [3:0] din,
    output wire [3:0] dout,
    output wire full,
    output wire empty
);
    reg [3:0] mem [0:7];
    reg [3:0] sp;
    assign empty = (sp == 4'd0);
    assign full = (sp == 4'd8);
    assign dout = mem[sp - 4'd1];
    always @(posedge clk)
        if (rst) sp <= 4'd0;
        else begin
            if (push && !full)  begin mem[sp] <= din; sp <= sp + 4'd1; end
            else if (pop && !empty) sp <= sp - 4'd1;
        end
endmodule

