module fifo4x8 (
    input wire clk,
    input wire rst,
    input wire wr,
    input wire rd,
    input wire [7:0] din,
    output reg [7:0] dout,
    output wire full,
    output wire empty
);
    reg [7:0] mem [0:3];
    reg [2:0] wptr, rptr;
    assign empty = (wptr == rptr);
    assign full  = (wptr[2] != rptr[2]) && (wptr[1:0] == rptr[1:0]);
    always @(posedge clk)
        if (rst) begin
            wptr <= 3'd0; rptr <= 3'd0; dout <= 8'd0;
        end else begin
            if (wr && !full) begin
                mem[wptr[1:0]] <= din;
                wptr <= wptr + 3'd1;
            end
            if (rd && !empty) begin
                dout <= mem[rptr[1:0]];
                rptr <= rptr + 3'd1;
            end
        end
endmodule

