module seq_moore_11 (
    input wire clk,
    input wire rst,
    input wire in,
    output wire y
);
    localparam S0 = 2'd0, S1 = 2'd1, S2 = 2'd2;
    reg [1:0] state, next;

    always @(posedge clk or posedge rst)
        if (rst) state <= S0;
        else     state <= next;

    always @(*) begin
        case (state)
            S0: next = in ? S1 : S0;
            S1: next = in ? S2 : S0;
            S2: next = in ? S2 : S0;
            default: next = S0;
        endcase
    end

    assign y = (state == S2);
endmodule

