module seq_moore_110 (
    input wire clk,
    input wire rst,
    input wire in,
    output wire y
);
    localparam S0 = 3'd0, S1 = 3'd1, S2 = 3'd2, S3 = 3'd3;
    reg [2:0] state, next;

    always @(posedge clk or posedge rst)
        if (rst) state <= S0;
        else     state <= next;

    always @(*) begin
        case (state)
            S0: next = in ? S1 : S0;
            S1: next = in ? S2 : S0;
            S2: next = in ? S2 : S3;
            S3: next = in ? S1 : S0;
            default: next = S0;
        endcase
    end

    assign y = (state == S3);
endmodule

template:
module onehot_fsm (
    input wire clk,
    input wire rst,
    input wire go,
    output reg [3:0] state
);
    // s0->s1->s2->s3->s0 while go=1
endmodule

testbench:
`timescale 1ns/1ps
module tb();
    reg clk=0, rst=1, go=0;
    wire [3:0] state;
    integer pass=0, fail=0;
    onehot_fsm dut(.clk(clk), .rst(rst), .go(go), .state(state));
    always #5 clk = ~clk;
    initial begin
        $display("== One-Hot FSM ==");
        @(posedge clk); #1 rst=0;
        if (state===4'b0001) pass=pass+1; else begin fail=fail+1; $display("FAIL: s0"); end
        go=1;
        @(posedge clk); #1;
        if (state===4'b0010) pass=pass+1; else begin fail=fail+1; $display("FAIL: s1"); end
        @(posedge clk); #1;
        if (state===4'b0100) pass=pass+1; else begin fail=fail+1; $display("FAIL: s2"); end
        go=0;
        @(posedge clk); #1;
        if (state===4'b0100) pass=pass+1; else begin fail=fail+1; $display("FAIL: hold"); end
