`timescale 1ns / 1ps

module elevator(
    input clk,
    input reset,
    input [4:0] floor_req,
    output reg [4:0] floor_pos
);
    reg [2:0] pos;
    integer k;
    reg up, down;
    always @(posedge clk or posedge reset) begin
        if (reset) pos <= 3'd0;
        else begin
            up = 1'b0; down = 1'b0;
            for (k = 0; k < 5; k = k + 1)
                if (floor_req[k]) begin
                    if (k > pos) up = 1'b1;
                    else if (k < pos) down = 1'b1;
                end
            if (up)        pos <= pos + 3'd1;
            else if (down) pos <= pos - 3'd1;
        end
    end
    always @(*) floor_pos = (5'b1 << pos);
endmodule

