module div3_fsm (
    input wire clk,
    input wire rst,
    input wire bit_in,
    output wire div3
);
    reg [1:0] state;
    always @(posedge clk)
        if (rst) state <= 2'd0;
        else case (state)
            2'd0: state <= bit_in ? 2'd1 : 2'd0;
            2'd1: state <= bit_in ? 2'd0 : 2'd2;
            2'd2: state <= bit_in ? 2'd2 : 2'd1;
            default: state <= 2'd0;
        endcase
    assign div3 = (state == 2'd0);
endmodule

