`timescale 1ns/1ps
module fsm_3bit_parity(
    input clk,
    input in,
    input rst,
    output reg y
);
    reg [1:0] cnt;   // how many bits of the current group have been seen
    reg       par;   // running parity of the current group

    always @(posedge clk) begin
        if (rst) begin
            cnt <= 2'd0;
            par <= 1'b0;
            y   <= 1'b0;
        end
        else if (cnt == 2'd2) begin
            // third bit of the group: latch the parity and restart
            y   <= par ^ in;
            cnt <= 2'd0;
            par <= 1'b0;
        end
        else begin
            cnt <= cnt + 2'd1;
            par <= par ^ in;
        end
    end
endmodule

