        clk = 0;
        forever #5 clk = ~clk;
    end

    // drive "b", check the Mealy output, then advance one state
    task step;
        input b;
        input e;
        begin
            in = b; #1;
            if(out !== e) $display("FAIL: in=%b expected out=%b got %b", b, e, out);
            else passed = passed + 1;
            @(posedge clk); #1;
        end
