        @(posedge clk); #1;
        if(out !== 0) $display("FAIL: Reset should clear output");
        else passed++;
        rst = 1;

        // sequence 101
        step(1'b1, 1'b0);   // 1     S0->S1
        step(1'b0, 1'b0);   // 10    S1->S2
        step(1'b1, 1'b1);   // 101   detect, S2->S1

        // overlapping 10101
        step(1'b0, 1'b0);   // 1010  S1->S2
        step(1'b1, 1'b1);   // 10101 detect, S2->S1

        // no match
        step(1'b0, 1'b0);   // S1->S2
        step(1'b0, 1'b0);   // S2->S0

        // partial pattern, then reset
        in = 1'b1; @(posedge clk); #1;   // S0->S1
        in = 1'b0; @(posedge clk); #1;   // S1->S2
        rst = 0; @(posedge clk); #1;     // -> S0
        if(out !== 0) $display("FAIL: Reset should clear output");
        else passed++;
        rst = 1;

        // detect again after reset
        step(1'b1, 1'b0);
        step(1'b0, 1'b0);
        step(1'b1, 1'b1);

        if(passed==12) $display("PASS: Mealy detector works correctly");
        else $display("FAIL: Some test cases failed");
        #20 $finish;
    end
