module seq_detector_mealy(
    input clk, rst, in,
    output reg out
);
    localparam S0 = 0, S1 = 1, S2 = 2;
    reg [1:0] state;
    always @(posedge clk) begin
        if (!rst)
            state <= S0;
        else begin
            case (state)
                S0: state <= in ? S1 : S0;
                S1: state <= in ? S1 : S2;
                S2: state <= in ? S1 : S0;
                default: state <= S0;
            endcase
        end
    end
    always @(*) begin
        out = (state == S2 && in == 1) ? 1'b1 : 1'b0;
