module traffic_light_ped (
    input wire clk,
    input wire rst,
    input wire ped,
    output reg red,
    output reg yellow,
    output reg green
);
    localparam R = 2'd0, G = 2'd1, Y = 2'd2;
    reg [1:0] state;
    reg [3:0] cnt;
    reg       ped_pending;   // a pedestrian asked for a longer red
    always @(posedge clk)
        if (rst) begin
            state <= R; cnt <= 4'd0; ped_pending <= 1'b0;
            red <= 1'b1; yellow <= 1'b0; green <= 1'b0;
        end else begin
            red <= 1'b0; yellow <= 1'b0; green <= 1'b0;
            if (ped) ped_pending <= 1'b1;
            case (state)
                R: begin
                    red <= 1'b1;
                    if (cnt == (ped_pending ? 4'd7 : 4'd3)) begin
                        state <= G; cnt <= 4'd0; ped_pending <= 1'b0;
                    end else cnt <= cnt + 4'd1;
                end
                G: begin
                    green <= 1'b1;
                    if (cnt == 4'd3) begin state <= Y; cnt <= 4'd0; end
                    else cnt <= cnt + 4'd1;
                end
                Y: begin
                    yellow <= 1'b1;
                    if (cnt == 4'd1) begin state <= R; cnt <= 4'd0; end
                    else cnt <= cnt + 4'd1;
                end
                default: state <= R;
            endcase
        end
endmodule

