module manchester_enc (
    input wire clk,
    input wire rst,
    input wire in_valid,
    input wire bit_in,
    output reg chip_out,
    output reg chip_valid
);
    reg phase;   // 0 = waiting for a bit, 1 = second half of a bit
    reg cur;

    always @(posedge clk)
        if (rst) begin
            phase      <= 1'b0;
            cur        <= 1'b0;
            chip_out   <= 1'b0;
            chip_valid <= 1'b0;
        end else if (!phase) begin
            if (in_valid) begin
                cur        <= bit_in;
                chip_out   <= ~bit_in;   // first half is the complement
                chip_valid <= 1'b1;
                phase      <= 1'b1;
            end else begin
                chip_valid <= 1'b0;
            end
        end else begin
            chip_out   <= cur;           // second half is the bit itself
            chip_valid <= 1'b1;
            phase      <= 1'b0;
        end
endmodule

