module round_robin_arbiter(
    input clk,
    input rst,
    input [3:0] req_sigs,
    output reg [3:0] grant_sigs
);
    reg [1:0] ptr;
    reg [3:0] g;
    integer k;
    always @(*) begin
        g = 4'b0;
        for (k = 0; k < 4; k = k + 1)
            if (req_sigs[(ptr + k) & 3] && g == 4'b0)
                g = (4'b1 << ((ptr + k) & 3));
    end
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            grant_sigs <= 4'b0;
            ptr <= 2'd0;
        end else begin
            grant_sigs <= g;
            case (g)
                4'b0001: ptr <= 2'd1;
                4'b0010: ptr <= 2'd2;
                4'b0100: ptr <= 2'd3;
                4'b1000: ptr <= 2'd0;
                default: ptr <= ptr;
            endcase
        end
    end
endmodule

