module spi_master (
    input wire clk,
    input wire rst,
    input wire start,
    input wire [7:0] data,
    output reg sclk,
    output reg mosi,
    output reg busy
);
    reg [3:0] phase;   // 0..15 half-clocks
    reg [7:0] shift;
    always @(posedge clk)
        if (rst) begin
            sclk<=0; mosi<=0; busy<=0; phase<=0;
        end else if (!busy) begin
            sclk<=0; mosi<=0;
            if (start) begin
                shift<=data; busy<=1; phase<=0;
            end
        end else begin
            phase <= phase + 1'b1;
            // MSB drive on even phase, sclk rise on odd, then fall
            if (phase[0]==0) begin
                mosi <= shift[7];
                sclk <= 1'b0;
            end else begin
                sclk <= 1'b1;
                shift <= {shift[6:0], 1'b0};
            end
            if (phase==4'd15) begin
                busy <= 1'b0;
                sclk <= 1'b0;
            end
        end
endmodule

