    always @(posedge clk)
        if (rst) begin parity<=0; cnt<=0; parity_ok<=0; end
        else begin
            parity_ok <= 0;
            if (in_valid) begin
                parity <= parity ^ bit_in;
                if (cnt == 4'd7) begin
                    parity_ok <= parity ^ bit_in; // includes current bit
                    parity <= 0;
                    cnt <= 0;
                end else cnt <= cnt + 4'd1;
            end
        end
