solution:
module mult2cycle (
    input wire clk,
    input wire rst,
    input wire valid_in,
    input wire [7:0] a,
    input wire [7:0] b,
    output reg valid_out,
    output reg [15:0] product
);
    // Two-cycle latency: valid_mid one cycle after valid_in, valid_out one
    // cycle after that.
    reg        valid_mid;     // stage 1 handshake
    reg [15:0] partial;       // stage 1 arithmetic result
    reg        valid_mid2;    // stage 2 handshake
    reg [15:0] partial2;      // stage 2 register

    always @(posedge clk)
        if (rst) begin
            valid_mid  <= 1'b0;
            partial    <= 16'd0;
            valid_mid2 <= 1'b0;
            partial2   <= 16'd0;
            valid_out  <= 1'b0;
            product    <= 16'd0;
        end else begin
            valid_mid  <= valid_in;    // capture operands
            partial    <= a * b;       // multiply in stage 1
            valid_mid2 <= valid_mid;
            partial2   <= partial;
            valid_out  <= valid_mid2;
            product    <= partial2;
        end
endmodule

