        a=8'd255;b=8'd255;c=8'd255;#1; if (s===9'd765) pass=pass+1; else begin fail=fail+1; $display("FAIL: 765 got %0d", s); end
        a=8'd0;  b=8'd0;  c=8'd0;  #1; if (s===9'd0)   pass=pass+1; else begin fail=fail+1; $display("FAIL: 0"); end
        if (fail == 0) $display("PASS: all %0d checks passed", pass);
        else           $display("FAIL: %0d check(s) failed", fail);
