solution:
module csa3_8bit (
    input wire [7:0] a, b, c,
    output wire [8:0] sum
);
    // 3:2 compressor: sum_bits = a^b^c, carry_bits = majority(a,b,c)
    wire [7:0] s_bits = a ^ b ^ c;
    wire [7:0] c_bits = (a & b) | (b & c) | (a & c);
    // Combine: sum_bits + (carry_bits << 1)
    assign sum = {1'b0, s_bits} + {c_bits, 1'b0};
endmodule

