module pulse_sync_cdc (
    input wire src_clk,
    input wire dst_clk,
    input wire rst,
    input wire src_pulse,
    output wire dst_pulse
);
    reg src_toggle;
    always @(posedge src_clk or posedge rst)
        if (rst) src_toggle <= 1'b0;
        else if (src_pulse) src_toggle <= ~src_toggle;
    reg sync1, sync2, sync3;
    always @(posedge dst_clk or posedge rst)
        if (rst) begin sync1 <= 0; sync2 <= 0; sync3 <= 0; end
        else begin sync1 <= src_toggle; sync2 <= sync1; sync3 <= sync2; end
    assign dst_pulse = sync2 ^ sync3;
endmodule

