module div3_50duty (
    input wire clk,
    input wire rst,
    output reg clk_out
);
    // Two counters: one on posedge, one on negedge; OR of their toggles gives 50% duty
    reg [1:0] cnt_p, cnt_n;
    reg toggle_p, toggle_n;
    always @(posedge clk or posedge rst)
        if (rst) begin cnt_p <= 2'd0; toggle_p <= 1'b0; end
        else if (cnt_p == 2'd2) begin cnt_p <= 2'd0; toggle_p <= ~toggle_p; end
        else cnt_p <= cnt_p + 2'd1;
    always @(negedge clk or posedge rst)
        if (rst) begin cnt_n <= 2'd0; toggle_n <= 1'b0; end
        else if (cnt_n == 2'd2) begin cnt_n <= 2'd0; toggle_n <= ~toggle_n; end
        else cnt_n <= cnt_n + 2'd1;
    always @(*) clk_out = toggle_p | toggle_n;
endmodule

