solution:
module missing_num (
    input wire clk,
    input wire rst,
    input wire in_valid,
    input wire last,
    input wire [7:0] num,
    output reg [7:0] missing
);
    // XOR trick: XOR every received number together with every number in the
    // expected range 1..N.  Everything cancels except the missing value.
    // Only N-1 numbers arrive, so we track idx_xor = XOR(1..k) for the k-th
    // received number and add the final index N = k+1 to complete 1..N.
    reg [7:0] xor_acc;   // XOR of the received numbers
    reg [7:0] idx_xor;   // XOR of 1..k
    reg [7:0] cnt;       // how many numbers have arrived

    always @(posedge clk)
        if (rst) begin
            xor_acc <= 8'd0;
            idx_xor <= 8'd0;
            cnt     <= 8'd0;
            missing <= 8'd0;
        end else if (in_valid) begin
            xor_acc <= xor_acc ^ num;
            idx_xor <= idx_xor ^ (cnt + 8'd1);
            cnt     <= cnt + 8'd1;
            if (last)
                // XOR(received) ^ XOR(1..N) with N = cnt + 2 here
                missing <= (xor_acc ^ num) ^ (idx_xor ^ (cnt + 8'd1)) ^ (cnt + 8'd2);
        end
endmodule

