module div3_detector (
    input wire clk,
    input wire rst,
    input wire bit_in,
    output reg div3
);
    reg [1:0] rem;
    always @(posedge clk)
        if (rst) rem <= 2'd0;
        else case (rem)
            2'd0: rem <= bit_in ? 2'd1 : 2'd0;
            2'd1: rem <= bit_in ? 2'd0 : 2'd2;
            2'd2: rem <= bit_in ? 2'd2 : 2'd1;
        endcase
    always @(*) div3 = (rem == 2'd0);
endmodule

