solution:
module clk_mux_glitchfree (
    input wire clk0,
    input wire clk1,
    input wire rst,
    input wire sel,
    output wire clk_out
);
    reg q0, q1;
    // In clk0 domain, only allow when sel==0
    always @(posedge clk0 or posedge rst)
        if (rst) q0 <= 1'b0;
        else     q0 <= ~sel & ~q1;
    always @(posedge clk1 or posedge rst)
        if (rst) q1 <= 1'b0;
        else     q1 <= sel & ~q0;
    assign clk_out = (clk0 & q0) | (clk1 & q1);
endmodule

