solution:
module rr_arbiter (
    input wire clk,
    input wire rst,
    input wire [3:0] req,
    output reg [3:0] grant
);
    reg [1:0] ptr;
    reg [3:0] g;
    integer i;
    always @(*) begin
        g = 4'b0;
        for (i=0;i<4;i=i+1)
            if (req[(ptr + i) & 3] && g == 4'b0)
                g = 4'b1 << ((ptr + i) & 3);
    end
    always @(posedge clk or posedge rst)
        if (rst) begin grant<=0; ptr<=0; end
        else begin
            grant <= g;
            case (g)
                4'b0001: ptr <= 2'd1;
                4'b0010: ptr <= 2'd2;
                4'b0100: ptr <= 2'd3;
                4'b1000: ptr <= 2'd0;
                default: ptr <= ptr;
            endcase
        end
endmodule

