solution:
module stuck_at_detect (
    input wire clk,
    input wire rst,
    input wire in_valid,
    input wire [7:0] sample,
    output reg [7:0] stuck
);
    // One saturating counter per bit position, for 0-runs and 1-runs.
    reg [7:0] cnt0 [0:7];
    reg [7:0] cnt1 [0:7];
    integer i;

    always @(posedge clk)
        if (rst) begin
            for (i = 0; i < 8; i = i + 1) begin
                cnt0[i] <= 8'd0;
                cnt1[i] <= 8'd0;
            end
            stuck <= 8'd0;
        end else if (in_valid) begin
            for (i = 0; i < 8; i = i + 1) begin
                if (sample[i]) begin
                    cnt1[i] <= (cnt1[i] >= 8'd100) ? 8'd100 : cnt1[i] + 8'd1;
                    cnt0[i] <= 8'd0;
                    // this sample makes the run cnt1[i]+1 long
                    stuck[i] <= (cnt1[i] >= 8'd99);
                end else begin
                    cnt0[i] <= (cnt0[i] >= 8'd100) ? 8'd100 : cnt0[i] + 8'd1;
                    cnt1[i] <= 8'd0;
                    stuck[i] <= (cnt0[i] >= 8'd99);
                end
            end
        end
endmodule

