module b64_decode (
    input wire [7:0] c,
    output reg [5:0] v,
    output reg valid
);
    always @(*) begin
        valid = 1'b1;
        if      (c >= "A" && c <= "Z") v = c - "A";
        else if (c >= "a" && c <= "z") v = c - "a" + 6'd26;
        else if (c >= "0" && c <= "9") v = c - "0" + 6'd52;
        else if (c == "+") v = 6'd62;
        else if (c == "/") v = 6'd63;
        else begin v = 6'd0; valid = 1'b0; end
    end
endmodule

