module can_stuffer (
    input wire clk,
    input wire rst,
    input wire in_valid,
    input wire in_bit,
    output reg out_valid,
    output reg out_bit
);
    reg [2:0] cnt;
    reg last_bit;
    reg need_stuff;
    always @(posedge clk)
        if (rst) begin
            cnt<=0; last_bit<=0; out_valid<=0; out_bit<=0; need_stuff<=0;
        end else begin
            out_valid <= 1'b0;
            if (need_stuff) begin
                out_valid <= 1'b1;
                out_bit <= ~last_bit;
                need_stuff <= 1'b0;
                cnt <= 3'd1; // count the stuffed bit as the first of the new run
                last_bit <= ~last_bit;
            end else if (in_valid) begin
                out_valid <= 1'b1;
                out_bit <= in_bit;
                if (in_bit == last_bit) begin
                    if (cnt == 3'd4) need_stuff <= 1'b1;
                    else cnt <= cnt + 3'd1;
                end else cnt <= 3'd1;
                last_bit <= in_bit;
            end
        end
endmodule

