    wire done;
    integer pass=0, fail=0;
    inet_checksum dut(.clk(clk), .rst(rst), .in_valid(v), .last(last), .word(w), .checksum(csum), .done(done));
    always #5 clk = ~clk;
    task send(input [15:0] x, input l);
        begin
            @(negedge clk); w=x; v=1; last=l;
            @(posedge clk); #1;
            @(negedge clk); v=0; last=0;
        end
    endtask
    initial begin
        $display("== Internet Checksum ==");
        @(posedge clk); #1 rst=0;
        // Sum 0x0001 + 0x0002 + 0x0003 = 0x0006 => checksum = ~6 = 0xFFF9
        send(16'h0001, 0);
        send(16'h0002, 0);
        send(16'h0003, 1);
        if (csum===16'hFFF9 && done===1) pass=pass+1; else begin fail=fail+1; $display("FAIL: csum=%h done=%b", csum, done); end
        // End-around carry case: 0xFFFF + 0x0001 = 0x10000 -> fold to 0x0001 -> ~1 = 0xFFFE
        rst=1; @(posedge clk); #1; rst=0;
        send(16'hFFFF, 0);
        send(16'h0001, 1);
        if (csum===16'hFFFE && done===1) pass=pass+1; else begin fail=fail+1; $display("FAIL: fold csum=%h done=%b", csum, done); end
        if (fail == 0) $display("PASS: all %0d tests passed", pass);
        else           $display("FAIL: %0d test(s) failed", fail);
