module inet_checksum (
    input wire clk,
    input wire rst,
    input wire in_valid,
    input wire last,
    input wire [15:0] word,
    output reg [15:0] checksum,
    output reg done
);
    reg [31:0] acc;
    // Ones' complement addition: fold the carry back into the low half.
    // Two folds are enough because the widest possible sum is 0x2FFFD.
    wire [31:0] f0 = acc[15:0] + word + {16'b0, acc[31:16]};
    wire [31:0] f1 = f0[15:0] + f0[31:16];
    wire [31:0] f2 = f1[15:0] + f1[31:16];
    always @(posedge clk)
        if (rst) begin
            acc <= 32'd0; checksum <= 16'd0; done <= 1'b0;
        end else begin
            done <= 1'b0;
            if (in_valid) begin
                acc <= f2;
                if (last) begin
                    checksum <= ~f2[15:0];
                    done <= 1'b1;
                    acc <= 32'd0;
                end
            end
        end
endmodule

