solution:
module rle_encoder (
    input wire clk,
    input wire rst,
    input wire in_valid,
    input wire last,
    input wire [7:0] in_byte,
    output reg out_valid,
    output reg [7:0] out_byte
);
    // The run accumulator runs on every accepted input byte; finished
    // (count, value) pairs are queued so the 2-cycle payout never drops an
    // incoming byte.
    reg [7:0] prev;
    reg [7:0] cnt;             // 0 = no run in progress

    reg [7:0] mem [0:7];       // output byte queue (depth 8)
    reg [2:0] wptr, rptr;
    reg [3:0] used;

    wire [3:0] n_push =
        !in_valid                       ? 4'd0 :
        (cnt == 8'd0)                   ? (last ? 4'd2 : 4'd0) :
        (in_byte == prev)               ? ((last || cnt == 8'd255) ? 4'd2 : 4'd0) :
                                          (last ? 4'd4 : 4'd2);
    wire do_pop = (used != 4'd0);

    always @(*) begin
        out_valid = do_pop;
        out_byte  = do_pop ? mem[rptr] : 8'd0;
    end

    always @(posedge clk)
        if (rst) begin
            prev <= 0; cnt <= 0; wptr <= 0; rptr <= 0; used <= 0;
        end else begin
            if (in_valid) begin
                if (cnt == 8'd0) begin
                    prev <= in_byte;
                    cnt  <= 8'd1;
                    if (last) begin
                        mem[wptr] <= 8'd1; mem[wptr + 3'd1] <= in_byte;
                        wptr <= wptr + 3'd2;
                        cnt  <= 8'd0;
                    end
                end else if (in_byte == prev) begin
                    if (last) begin
                        mem[wptr] <= cnt + 8'd1; mem[wptr + 3'd1] <= prev;
                        wptr <= wptr + 3'd2;
                        cnt  <= 8'd0;
                    end else if (cnt == 8'd255) begin
                        mem[wptr] <= cnt; mem[wptr + 3'd1] <= prev;
                        wptr <= wptr + 3'd2;
                        cnt  <= 8'd1;
                    end else begin
                        cnt <= cnt + 8'd1;
                    end
                end else begin
                    mem[wptr] <= cnt; mem[wptr + 3'd1] <= prev;
                    wptr <= wptr + 3'd2;
                    prev <= in_byte;
                    cnt  <= 8'd1;
                    if (last) begin
                        mem[wptr + 3'd2] <= 8'd1; mem[wptr + 3'd3] <= in_byte;
                        wptr <= wptr + 3'd4;
                        cnt  <= 8'd0;
                    end
                end
            end
            if (do_pop) rptr <= rptr + 3'd1;
            used <= used + n_push - (do_pop ? 4'd1 : 4'd0);
        end
endmodule

