module tb();
    reg clk=0, rst=1, p=0;
    wire [7:0] cnt;
    wire vw, lk, sp;
    integer pass=0, fail=0, i, seen;
    abs_monitor dut(.clk(clk), .rst(rst), .sensor_pulse(p), .pulses_count(cnt), .valid_window(vw), .locked(lk), .spin(sp));
    always #5 clk = ~clk;
    initial begin
        $display("== ABS Monitor ==");
        @(posedge clk); #1 rst=0;
        // One pulse in a whole window: the wheel is locked
        @(negedge clk); p=1; @(posedge clk); #1; @(negedge clk); p=0;
        seen = 0;
        for (i=0; i<120; i=i+1) begin
            @(posedge clk); #1;
            if (vw) begin seen = 1; i = 1000; end
        end
        if (seen===1 && lk===1 && cnt<=8'd2) pass=pass+1;
        else begin fail=fail+1; $display("FAIL: locked cnt=%0d lk=%b seen=%0d", cnt, lk, seen); end
        // Reset, then 95 pulses inside one window: the wheel spins too fast
        rst=1; @(posedge clk); #1; rst=0;
        @(negedge clk); p=1;
        for (i=0; i<95; i=i+1) @(posedge clk);
        @(negedge clk); p=0;
        seen = 0;
        for (i=0; i<120; i=i+1) begin
            @(posedge clk); #1;
            if (vw) begin seen = 1; i = 1000; end
        end
        if (seen===1 && sp===1) pass=pass+1;
        else begin fail=fail+1; $display("FAIL: spin cnt=%0d sp=%b seen=%0d", cnt, sp, seen); end
        if (fail == 0) $display("PASS: all %0d checks passed", pass);
        else           $display("FAIL: %0d check(s) failed", fail);
        $finish;
    end
endmodule

solution:
module abs_monitor (
    input wire clk,
    input wire rst,
    input wire sensor_pulse,
    output reg [7:0] pulses_count,
    output reg valid_window,
    output reg locked,
    output reg spin
);
    reg [7:0] cnt;
    reg [7:0] wcnt;
    always @(posedge clk)
        if (rst) begin
            cnt<=0; wcnt<=0; pulses_count<=0; valid_window<=0; locked<=0; spin<=0;
        end else begin
            valid_window <= 1'b0;
            if (sensor_pulse && cnt < 8'd255) cnt <= cnt + 8'd1;
            // Fixed 100-clock measurement window (was 200).
            if (wcnt == 8'd99) begin
                pulses_count <= cnt;
                valid_window <= 1'b1;
                locked <= (cnt <= 8'd2);
                spin   <= (cnt >= 8'd90);
                cnt <= 0;
                wcnt <= 0;
            end else wcnt <= wcnt + 8'd1;
        end
endmodule

