solution:
module atm_bills (
    input wire [15:0] amount,
    output reg [7:0] n100,
    output reg [7:0] n50,
    output reg [7:0] n20,
    output reg ready,
    output reg error
);
    reg [15:0] rem;
    always @(*) begin
        n100 = 0; n50 = 0; n20 = 0; ready = 0; error = 0;
        if (amount % 16'd10 != 0) begin
            error = 1'b1;
        end else begin
            n100 = amount / 16'd100;
            rem = amount % 16'd100;
            n50 = rem / 16'd50;
            rem = rem % 16'd50;
            n20 = rem / 16'd20;
            rem = rem % 16'd20;
            if (rem != 0) begin
                n100 = amount / 16'd100;
                rem = amount % 16'd100;
                n50 = 0;
                n20 = rem / 16'd20;
                rem = rem % 16'd20;
                if (rem != 0) begin
                    error = 1'b1; n100 = 0; n50 = 0; n20 = 0;
                end else begin
                    ready = 1'b1;
                end
            end else begin
                ready = 1'b1;
            end
        end
    end
endmodule

