module shutter (
    input wire clk,
    input wire rst,
    input wire shutter,
    input wire shutter_release,
    input wire [7:0] exposure,
    output reg fire,
    output reg done
);
    localparam IDLE=0, WAIT=1, OPEN=2, DONE=3;
    reg [1:0] st;
    reg [7:0] cnt;
    always @(posedge clk)
        if (rst) begin st<=IDLE; cnt<=0; fire<=0; done<=0; end
        else begin
            fire<=0; done<=0;
            case (st)
                IDLE: if (shutter) begin cnt<=8'd20; st<=WAIT; end
                WAIT: begin
                    if (shutter_release) st<=IDLE;
                    else if (cnt == 0) begin fire<=1; cnt<=exposure; st<=OPEN; end
                    else cnt <= cnt - 1;
                end
                OPEN: begin
                    if (cnt == 0) begin done<=1; st<=IDLE; end
                    else cnt <= cnt - 1;
                end
                default: st <= IDLE;
            endcase
        end
endmodule

