module cash_register (
    input wire clk,
    input wire rst,
    input wire calc,
    input wire [15:0] price,
    input wire [15:0] paid,
    output reg [15:0] change,
    output reg [7:0] n100,
    output reg [7:0] n25,
    output reg [7:0] n10,
    output reg [7:0] n5,
    output reg [7:0] n1,
    output reg change_valid,
    output reg error
);
    always @(posedge clk)
        if (rst) begin
            change<=0; n100<=0; n25<=0; n10<=0; n5<=0; n1<=0; change_valid<=0; error<=0;
        end else begin
            change_valid <= 0; error <= 0;
            if (calc) begin
                if (paid < price) begin
                    error <= 1;
                end else begin
                    change <= paid - price;
                    n100 <= (paid - price) / 16'd100;
                    n25  <= ((paid - price) % 16'd100) / 16'd25;
                    n10  <= (((paid - price) % 16'd100) % 16'd25) / 16'd10;
                    n5   <= ((((paid - price) % 16'd100) % 16'd25) % 16'd10) / 16'd5;
                    n1   <= (((((paid - price) % 16'd100) % 16'd25) % 16'd10) % 16'd5);
                    change_valid <= 1;
                end
            end
        end
endmodule

