module guitar_tuner (
    input wire [15:0] freq,
    input wire [2:0] string_sel,
    output reg sharp,
    output reg flat,
    output reg in_tune
);
    reg [15:0] target;
    always @(*) begin
        case (string_sel)
            3'd0: target = 16'd82;
            3'd1: target = 16'd110;
            3'd2: target = 16'd146;
            3'd3: target = 16'd196;
            3'd4: target = 16'd246;
            3'd5: target = 16'd329;
            default: target = 16'd82;
        endcase
        sharp = (freq > target + 16'd3);
        flat  = (freq + 16'd3 < target);
        in_tune = !sharp && !flat;
    end
endmodule

