    input wire rst,
    input wire tare,
    input wire unit,
    input wire [15:0] raw,
    output reg [15:0] displayed
);
    reg [15:0] offset;
    // Tared weight is computed combinationally so the display does not lag the
    // raw input by an extra cycle.
    wire [15:0] grams = (raw >= offset) ? (raw - offset) : 16'd0;
    always @(posedge clk)
        if (rst) begin offset <= 16'd0; displayed <= 16'd0; end
        else begin
            if (tare) offset <= raw;
            displayed <= unit ? (grams / 16'd28) : grams;
