module microwave (
    input wire clk,
    input wire rst,
    input wire start,
    input wire stop,
    input wire door_open,
    input wire [7:0] time_in,
    output reg magnetron,
    output reg beep
);
    reg [7:0] cnt;
    reg [2:0] beep_cnt;
    reg running;
    always @(posedge clk)
        if (rst) begin cnt<=0; beep<=0; magnetron<=0; beep_cnt<=0; running<=0; end
        else if (!running) begin
            beep <= 0;
            if (start) begin cnt <= time_in; running <= 1; magnetron <= 1; end
        end else begin
            if (stop) begin running<=0; magnetron<=0; end
            else if (door_open) magnetron <= 0;
            else begin
                magnetron <= 1;
                if (cnt == 0) begin running<=0; beep<=1; beep_cnt<=3; magnetron<=0; end
                else cnt <= cnt - 1;
            end
            if (beep_cnt > 0) begin beep<=1; beep_cnt<=beep_cnt-1; end
        end
endmodule

