module turnstile (
    input wire clk,
    input wire rst,
    input wire ticket,
    input wire entry_sensor,
    input wire exit_sensor,
    output reg gate_open,
    output reg alarm
);
    // `inside` is a SystemVerilog keyword, so the flag is `occupied`.
    reg armed;
    reg occupied;
    wire accept = ticket && !occupied;
    always @(posedge clk)
        if (rst) begin
            armed <= 0; occupied <= 0; gate_open <= 0; alarm <= 0;
        end else begin
            alarm <= 1'b0;
            if (accept) armed <= 1'b1;
            if (entry_sensor && (armed || accept)) begin
                occupied  <= 1'b1;
                armed     <= 1'b0;
                gate_open <= 1'b0;
            end else if (entry_sensor && !occupied) begin
                alarm     <= 1'b1;
                gate_open <= 1'b0;
            end else begin
                gate_open <= armed || accept;
            end
            if (exit_sensor && occupied) occupied <= 1'b0;
        end
endmodule

