module elevator3 (
    input wire clk,
    input wire rst,
    input wire call0,
    input wire call1,
    input wire call2,
    output reg [1:0] floor,
    output reg stop
);
    reg [2:0] req;
    reg dir; // 1=up, 0=down
    always @(posedge clk)
        if (rst) begin
            floor <= 0; req <= 0; stop <= 0; dir <= 1'b1;
        end else begin
            stop <= 0;
            if (call0) req[0] <= 1'b1;
            if (call1) req[1] <= 1'b1;
            if (call2) req[2] <= 1'b1;
            if (req[floor]) begin
                stop <= 1'b1;
                req[floor] <= 1'b0;
            end else begin
                if (|req) begin
                    // move toward nearest requested floor
                    if (floor < 2 && ((req >> (floor + 1)) != 0)) floor <= floor + 1;
                    else if (floor > 0 && ((req & ((1<<floor)-1)) != 0)) floor <= floor - 1;
                end
            end
        end
endmodule

