module coffee_machine (
    input wire clk,
    input wire rst,
    input wire coin25,
    input wire coin10,
    output reg dispense,
    output reg change25,
    output reg change10
);
    reg [6:0] total;
    reg [6:0] change;
    reg [1:0] st;              // 0 = accept coins, 1 = pay out change
    wire [6:0] add    = coin25 ? 7'd25 : (coin10 ? 7'd10 : 7'd0);
    wire [6:0] ntotal = total + add;
    always @(posedge clk)
        if (rst) begin
            total<=0; change<=0; dispense<=0; change25<=0; change10<=0; st<=0;
        end else begin
            dispense<=0; change25<=0; change10<=0;
            case (st)
                2'd0: begin
                    if (coin25 || coin10) total <= ntotal;
                    if (ntotal >= 7'd50) begin
                        change   <= ntotal - 7'd50;
                        dispense <= 1'b1;
                        total    <= 7'd0;
                        st       <= 2'd1;
                    end
                end
                default: begin
                    if (change >= 7'd25) begin
                        change25 <= 1'b1; change <= change - 7'd25;
                    end else if (change >= 7'd10) begin
                        change10 <= 1'b1; change <= change - 7'd10;
                    end else begin
                        change <= 7'd0; st <= 2'd0;
                    end
                end
            endcase
        end
endmodule

