module crosswalk (
    input wire clk,
    input wire rst,
    input wire ped,
    output reg red,
    output reg green,
    output reg yellow,
    output reg walk
);
    localparam RED=0, GREEN=1, YELLOW=2;
    reg [1:0] st;
    reg [7:0] cnt;
    reg [7:0] red_len;
    reg ped_seen;
    always @(posedge clk)
        if (rst) begin
            st<=RED; cnt<=0; red_len<=40; walk<=0; ped_seen<=0;
        end else begin
            if (ped) begin
                if (st == RED) red_len <= 8'd20;
                else red_len <= 8'd60;
                ped_seen <= 1'b1;
            end
            cnt <= cnt + 8'd1;
            walk <= 0;
            case (st)
                RED: begin
                    if (ped_seen && cnt >= red_len - 10) walk <= 1;
                    if (cnt == red_len - 1) begin st<=GREEN; cnt<=0; red_len<=40; ped_seen<=0; end
                end
                GREEN: begin
                    if (cnt == 8'd59) begin st<=YELLOW; cnt<=0; end
                end
                YELLOW: begin
                    if (cnt == 8'd9) begin st<=RED; cnt<=0; end
                end
            endcase
        end
    always @(*) begin
        red    = (st==RED);
        green  = (st==GREEN);
        yellow = (st==YELLOW);
    end
endmodule

