    output reg refund
);
    reg [7:0] total;
    reg [2:0] r5, r10;
    reg [1:0] st;
    reg [7:0] change;
    always @(posedge clk)
        if (rst) begin
            total<=0; r5<=3; r10<=2; issue<=0; refund<=0; st<=0; change<=0;
        end else begin
            issue<=0; refund<=0;
            case (st)
                2'd0: begin
                    if (c5)  total <= total + 8'd5;
                    if (c10) total <= total + 8'd10;
                    if ((c5 && total+8'd5 >= 8'd20) || (c10 && total+8'd10 >= 8'd20)) begin
                        change <= (total + (c5?8'd5:c10?8'd10:8'd0)) - 8'd20;
                        st <= 2'd1;
                    end
                end
                2'd1: begin
                    if (change == 0) begin issue <= 1; st <= 2'd0; total <= 0; end
                    else if (change >= 10 && r10 > 0) begin r10 <= r10-1; change <= change-10; end
                    else if (change >= 5  && r5  > 0) begin r5  <= r5-1;  change <= change-5;  end
                    else begin refund <= 1; st <= 2'd0; total <= 0; change <= 0; end
                end
                default: st <= 2'd0;
            endcase
        end
endmodule

