module printer_queue (
    input wire clk,
    input wire rst,
    input wire new_job,
    output reg busy,
    output reg prints,
    output reg reject,
    output reg [2:0] queue_count
);
    reg [2:0] timer;
    always @(posedge clk)
        if (rst) begin busy<=0; prints<=0; reject<=0; queue_count<=0; timer<=0; end
        else begin
            prints<=0; reject<=0;
            if (new_job) begin
                if (queue_count < 3'd4) queue_count <= queue_count + 3'd1;
                else reject <= 1;
            end
            if (!busy) begin
                if (queue_count > 3'd0) begin
                    busy <= 1; prints <= 1; timer <= 3'd4;
                    queue_count <= queue_count - 3'd1;
                end
            end else begin
                prints <= 1;
                if (timer == 0) begin busy <= 0; prints <= 1; end
                else timer <= timer - 3'd1;
            end
        end
endmodule

