module fade_bulb (
    input wire clk,
    input wire rst,
    input wire turn_on,
    input wire turn_off,
    output reg [7:0] brightness,
    output reg bulb_on
);
    reg dir; // 1=up, 0=down
    always @(posedge clk)
        if (rst) begin brightness<=0; bulb_on<=0; dir<=0; end
        else begin
            if (turn_on) begin dir<=1; bulb_on<=1; end
            else if (turn_off) dir<=0;
            if (dir) begin
                if (brightness < 8'd255) brightness <= brightness + 8'd1;
                if (brightness == 8'd255) bulb_on <= 1;
            end else begin
                if (brightness > 8'd0) brightness <= brightness - 8'd1;
                if (brightness == 8'd1) bulb_on <= 0;
            end
        end
endmodule

