module pill_dispenser (
    input wire clk,
    input wire rst,
    input wire start,
    input wire taken,
    input wire [3:0] pills_per_day,
    output reg dispense,
    output reg alarm,
    output reg asleep
);
    localparam IDLE=0, WAIT_HOUR=1, DISPENSE=2, WAIT_TAKE=3, SLEEP=4;
    reg [2:0] st;
    reg [19:0] hour_timer;
    reg [3:0] pills_left;
    reg [7:0] take_timer;
    always @(posedge clk)
        if (rst) begin
            st<=IDLE; hour_timer<=0; pills_left<=0; take_timer<=0;
            dispense<=0; alarm<=0; asleep<=0;
        end else begin
            dispense<=0; alarm<=0;
            case (st)
                IDLE: if (start) begin pills_left <= pills_per_day; st <= WAIT_HOUR; hour_timer <= 20'd1000; asleep <= 0; end
                WAIT_HOUR: begin
                    asleep <= 1'b0;
                    if (hour_timer == 0) begin st <= DISPENSE; end
                    else hour_timer <= hour_timer - 1;
                end
                DISPENSE: begin
                    dispense <= 1;
                    pills_left <= pills_left - 1;
                    take_timer <= 8'd100;
                    st <= WAIT_TAKE;
                end
                WAIT_TAKE: begin
                    if (taken) begin
                        if (pills_left == 0) begin st <= SLEEP; hour_timer <= 20'd24000; asleep<=1; end
                        else begin st <= WAIT_HOUR; hour_timer <= 20'd1000; end
                    end else if (take_timer == 0) begin
                        alarm <= 1;
                    end else take_timer <= take_timer - 1;
                end
                SLEEP: begin
                    asleep <= 1;
                    if (hour_timer == 0) begin st <= IDLE; asleep <= 0; end
                    else hour_timer <= hour_timer - 1;
                end
            endcase
        end
endmodule

