module coin_return (
    input wire clk,
    input wire rst,
    input wire insert5,
    input wire insert10,
    input wire insert25,
    input wire return_btn,
    output reg [1:0] return_coin,
    output reg coin_valid
);
    reg [1:0] stack [0:7];
    reg [3:0] sp;
    reg       returning;       // draining the stack after return_btn
    wire any_insert = insert5 | insert10 | insert25;
    wire do_return  = returning | (return_btn && (sp > 0));
    always @(posedge clk)
        if (rst) begin
            sp <= 0; return_coin <= 0; coin_valid <= 0; returning <= 1'b0;
        end else begin
            coin_valid <= 1'b0;
            if (do_return) begin
                return_coin <= stack[sp - 1];
                coin_valid  <= 1'b1;
                sp          <= sp - 1;
                returning   <= (sp > 1);   // keep draining
            end else begin
                returning <= 1'b0;
                if (any_insert && sp < 8) begin
                    stack[sp] <= insert5 ? 2'd0 : (insert10 ? 2'd1 : 2'd2);
                    sp <= sp + 1;
                end
            end
        end
endmodule

