module washer (
    input wire clk,
    input wire rst,
    input wire start,
    input wire lid_open,
    output reg motor_on,
    output reg valve_open,
    output reg drain_on,
    output reg busy,
    output reg done
);
    localparam IDLE=0, FILL=1, WASH=2, DRAIN=3, RINSE=4, SPIN=5, DONE=6;
    reg [2:0] st, nst;
    reg [7:0] cnt;
    reg [7:0] limit;
    reg [7:0] next_cnt;
    always @(*) begin
        case (st)
            FILL:  limit = 8'd30;
            WASH:  limit = 8'd50;
            DRAIN: limit = 8'd20;
            RINSE: limit = 8'd30;
            SPIN:  limit = 8'd40;
            default: limit = 8'd0;
        endcase
    end
    always @(*) begin
        nst = st;
        next_cnt = cnt + 1;
        case (st)
            IDLE: if (start) begin nst=FILL; next_cnt=0; end
            FILL: if (!lid_open && cnt==limit-1) begin nst=WASH; next_cnt=0; end
            WASH: if (!lid_open && cnt==limit-1) begin nst=DRAIN; next_cnt=0; end
            DRAIN: if (!lid_open && cnt==limit-1) begin nst=RINSE; next_cnt=0; end
            RINSE: if (!lid_open && cnt==limit-1) begin nst=SPIN; next_cnt=0; end
            SPIN: if (!lid_open && cnt==limit-1) begin nst=DONE; next_cnt=0; end
            DONE: begin nst=IDLE; next_cnt=0; end
            default: nst=IDLE;
        endcase
    end
    always @(posedge clk)
        if (rst) begin st<=IDLE; cnt<=0; end
        else begin st<=nst; cnt<=next_cnt; end
    always @(*) begin
        motor_on = (st==WASH) || (st==SPIN);
        valve_open = (st==FILL) || (st==RINSE);
        drain_on = (st==DRAIN);
        busy = (st != IDLE);
        done = (st == DONE);
    end
endmodule

