module temp_histogram (
    input wire clk,
    input wire rst,
    input wire sample,
    input wire [2:0] temp,
    output reg [7:0] h0,
    output reg [7:0] h1,
    output reg [7:0] h2,
    output reg [7:0] h3,
    output reg [7:0] h4,
    output reg [7:0] h5,
    output reg [7:0] h6,
    output reg [7:0] h7
);
    always @(posedge clk) begin
        if (rst) begin h0<=0;h1<=0;h2<=0;h3<=0;h4<=0;h5<=0;h6<=0;h7<=0; end
        else if (sample) begin
            case (temp)
                3'd0: if (h0 != 8'hFF) h0 <= h0 + 8'd1;
                3'd1: if (h1 != 8'hFF) h1 <= h1 + 8'd1;
                3'd2: if (h2 != 8'hFF) h2 <= h2 + 8'd1;
                3'd3: if (h3 != 8'hFF) h3 <= h3 + 8'd1;
                3'd4: if (h4 != 8'hFF) h4 <= h4 + 8'd1;
                3'd5: if (h5 != 8'hFF) h5 <= h5 + 8'd1;
                3'd6: if (h6 != 8'hFF) h6 <= h6 + 8'd1;
                3'd7: if (h7 != 8'hFF) h7 <= h7 + 8'd1;
            endcase
        end
    end
endmodule
